{
  "openapi": "3.0.0",
  "info": {
    "title": "VibePass API",
    "description": "API endpoints for the VibePass Event Booking & OTT Streaming Explorer Platform.\n\n**Docs**: [/docs](/docs) (Swagger UI) · [/redoc](/redoc) (ReDoc) · [/openapi.json](/openapi.json) (schema)",
    "version": "1.0.0"
  },
  "paths": {
    "/api/auth/send-otp": {
      "post": {
        "summary": "Send OTP Code",
        "description": "Generates a cryptographically secure 6-digit numeric OTP code and emails it to the user via Nodemailer.",
        "tags": [
          "Authentication"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "email"
                ],
                "properties": {
                  "email": {
                    "type": "string",
                    "format": "email",
                    "example": "user@example.com"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "OTP sent successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "message": {
                      "type": "string",
                      "example": "Verification code sent to your email."
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing required email parameter",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Failed to send OTP",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/auth/verify-otp": {
      "post": {
        "summary": "Verify OTP Code",
        "description": "Matches verification code and email. Automatically registers new users in the database.",
        "tags": [
          "Authentication"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "email",
                  "otp"
                ],
                "properties": {
                  "email": {
                    "type": "string",
                    "format": "email",
                    "example": "user@example.com"
                  },
                  "otp": {
                    "type": "string",
                    "example": "123456"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "OTP verified successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "isNewUser": {
                      "type": "boolean",
                      "example": false
                    },
                    "user": {
                      "$ref": "#/components/schemas/User"
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Invalid OTP code, missing parameters, or code expired",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Database or unexpected error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/auth/google": {
      "post": {
        "summary": "Sign in with Google OAuth",
        "description": "Accepts user Google access token, queries profile data, and upserts user details in the database.",
        "tags": [
          "Authentication"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "accessToken"
                ],
                "properties": {
                  "accessToken": {
                    "type": "string",
                    "example": "ya29.a0AfH6SM..."
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Successfully authenticated user",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "isNewUser": {
                      "type": "boolean",
                      "example": false
                    },
                    "user": {
                      "$ref": "#/components/schemas/User"
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Invalid token or Google API query failure",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Internal server error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/bookings": {
      "get": {
        "summary": "Retrieve Bookings or Booked Seats",
        "description": "If `email` is passed, fetches the user's booking history records. If `eventId` is passed, returns a list of occupied seat identifiers.",
        "tags": [
          "Bookings"
        ],
        "parameters": [
          {
            "name": "email",
            "in": "query",
            "description": "User email address to load bookings history.",
            "required": false,
            "schema": {
              "type": "string",
              "format": "email"
            }
          },
          {
            "name": "eventId",
            "in": "query",
            "description": "Event ID to retrieve booked seats layout.",
            "required": false,
            "schema": {
              "type": "integer"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Operation successful",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "bookings": {
                      "type": "array",
                      "items": {
                        "$ref": "#/components/schemas/BookingRecord"
                      }
                    },
                    "seats": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      },
                      "example": [
                        "A1",
                        "A2",
                        "VIP-03"
                      ]
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing required query parameters",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Internal server error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "post": {
        "summary": "Hold or Confirm Seats",
        "description": "Reserves seats (pending hold) or transitions a pending booking to confirmed.",
        "tags": [
          "Bookings"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "email",
                  "eventId",
                  "seats"
                ],
                "properties": {
                  "email": {
                    "type": "string",
                    "format": "email",
                    "example": "user@example.com"
                  },
                  "name": {
                    "type": "string",
                    "example": "Jane Doe"
                  },
                  "phone": {
                    "type": "string",
                    "example": "+919876543210"
                  },
                  "eventId": {
                    "type": "integer",
                    "example": 1
                  },
                  "seats": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    },
                    "example": [
                      "A1",
                      "A2"
                    ]
                  },
                  "totalPrice": {
                    "type": "integer",
                    "example": 1200
                  },
                  "bookingStartedAt": {
                    "type": "string",
                    "description": "Epoch timestamp when booking hold started.",
                    "example": "1719999999000"
                  },
                  "paymentMethod": {
                    "type": "string",
                    "default": "card",
                    "example": "card"
                  },
                  "status": {
                    "type": "string",
                    "enum": [
                      "pending",
                      "confirmed",
                      "cancelled"
                    ],
                    "default": "confirmed",
                    "example": "pending"
                  },
                  "seatsBooked": {
                    "type": "integer",
                    "example": 2
                  },
                  "cancelBookingId": {
                    "type": "integer",
                    "description": "Optional booking ID to release/cancel first.",
                    "example": 12
                  },
                  "bookingId": {
                    "type": "integer",
                    "description": "Optional existing pending booking ID to update to confirmed status.",
                    "example": 14
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Booking hold placed or confirmed successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "bookingId": {
                      "type": "integer",
                      "example": 45
                    },
                    "message": {
                      "type": "string",
                      "example": "Booking stored successfully in database."
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing inputs or session timestamp check failure",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "409": {
            "description": "Conflict: seats already occupied/held",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Internal database insertion/update error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "delete": {
        "summary": "Release Pending Reservation",
        "description": "Releases a pending reservation from the database.",
        "tags": [
          "Bookings"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "bookingId"
                ],
                "properties": {
                  "bookingId": {
                    "type": "integer",
                    "example": 45
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Reservation released",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "message": {
                      "type": "string",
                      "example": "Pending booking released."
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing booking ID parameter",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Deletion failed",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/bookings/verify": {
      "get": {
        "summary": "Verify Seat Occupancy Status",
        "description": "Verifies whether specified seat keys are already occupied or held for an event.",
        "tags": [
          "Bookings"
        ],
        "parameters": [
          {
            "name": "eventId",
            "in": "query",
            "required": true,
            "schema": {
              "type": "integer",
              "example": 1,
              "default": 1
            }
          },
          {
            "name": "seats",
            "in": "query",
            "description": "Comma-separated list of seat tags to verify",
            "required": true,
            "schema": {
              "type": "string",
              "example": "A1,A2,B5",
              "default": "A1,A2,B5"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Verification data returned",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "verifiedSeats": {
                      "type": "object",
                      "description": "Key-value map where true = occupied/held, false = open/available.",
                      "additionalProperties": {
                        "type": "boolean"
                      },
                      "example": {
                        "A1": true,
                        "A2": false,
                        "B5": false
                      }
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing parameters",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Verification failed",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/bookings/pass-status": {
      "get": {
        "summary": "Check Category Pass Availabilities",
        "description": "Retrieves real-time ticket quantity details and availability statuses (Available, Filling Fast, Sold Out) per pass tier (VIP, Gold, Silver, General).",
        "tags": [
          "Bookings"
        ],
        "parameters": [
          {
            "name": "eventId",
            "in": "query",
            "required": true,
            "schema": {
              "type": "integer",
              "example": 1,
              "default": 1
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Pass status map retrieved",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "passes": {
                      "type": "object",
                      "properties": {
                        "general": {
                          "$ref": "#/components/schemas/PassTier"
                        },
                        "silver": {
                          "$ref": "#/components/schemas/PassTier"
                        },
                        "gold": {
                          "$ref": "#/components/schemas/PassTier"
                        },
                        "vip": {
                          "$ref": "#/components/schemas/PassTier"
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing parameters",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Database computation failure",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/events": {
      "get": {
        "summary": "List Events",
        "description": "Fetches database event listings, filtering by type, category, or location state.",
        "tags": [
          "Events"
        ],
        "parameters": [
          {
            "name": "type",
            "in": "query",
            "description": "Event filter tag (e.g. 'featured' or 'trending')",
            "required": false,
            "schema": {
              "type": "string",
              "example": "featured",
              "default": "featured"
            }
          },
          {
            "name": "category",
            "in": "query",
            "description": "Event category (e.g. 'comedy', 'concerts', 'sports', 'movies')",
            "required": false,
            "schema": {
              "type": "string",
              "example": "comedy",
              "default": "comedy"
            }
          },
          {
            "name": "state",
            "in": "query",
            "description": "Sub-string location state filter (e.g. 'Karnataka', 'Delhi')",
            "required": false,
            "schema": {
              "type": "string",
              "example": "Karnataka",
              "default": "Karnataka"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "List of events matching filters",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "events": {
                      "type": "array",
                      "items": {
                        "$ref": "#/components/schemas/Event"
                      }
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "Listing query execution failure",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/events/search": {
      "get": {
        "summary": "Autosuggest / Search Events",
        "description": "Performs quick full-text wildcard search queries across event titles, category, description, and organizers.",
        "tags": [
          "Events"
        ],
        "parameters": [
          {
            "name": "q",
            "in": "query",
            "description": "Search query input text",
            "required": true,
            "schema": {
              "type": "string",
              "example": "standup",
              "default": "standup"
            }
          },
          {
            "name": "state",
            "in": "query",
            "description": "Optional location state filter override",
            "required": false,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "limit",
            "in": "query",
            "description": "Max limit of items to return",
            "required": false,
            "schema": {
              "type": "integer",
              "default": 6
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Matching results returned",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "results": {
                      "type": "array",
                      "items": {
                        "$ref": "#/components/schemas/Event"
                      }
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "Search failure",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/events/review": {
      "get": {
        "summary": "List Event Reviews",
        "description": "Retrieves the list of reviews submitted for a specific event.",
        "tags": [
          "Reviews & Feedback"
        ],
        "parameters": [
          {
            "name": "eventId",
            "in": "query",
            "required": true,
            "schema": {
              "type": "integer",
              "example": 1,
              "default": 1
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Review list retrieved",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "reviews": {
                      "type": "array",
                      "items": {
                        "$ref": "#/components/schemas/Review"
                      }
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing parameters",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Internal error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "post": {
        "summary": "Add Review to Event",
        "description": "Saves a user rating and review text to the database and returns the updated listing.",
        "tags": [
          "Reviews & Feedback"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "eventId",
                  "userId",
                  "rating",
                  "comment"
                ],
                "properties": {
                  "eventId": {
                    "type": "integer",
                    "example": 1
                  },
                  "userId": {
                    "type": "integer",
                    "example": 1
                  },
                  "rating": {
                    "type": "integer",
                    "minimum": 1,
                    "maximum": 5,
                    "example": 5
                  },
                  "comment": {
                    "type": "string",
                    "example": "Amazing performance! Loved the energy."
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Review submitted successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "message": {
                      "type": "string",
                      "example": "Review added successfully"
                    },
                    "reviews": {
                      "type": "array",
                      "items": {
                        "$ref": "#/components/schemas/Review"
                      }
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing params or rating value bounds violated",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized: user does not exist",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "Event not found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Database write failure",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/events/like": {
      "get": {
        "summary": "Fetch Event Likes Stats",
        "description": "Loads cumulative likes count and checks if the given user has liked the target event.",
        "tags": [
          "Likes & Favourites"
        ],
        "parameters": [
          {
            "name": "eventId",
            "in": "query",
            "required": true,
            "schema": {
              "type": "integer",
              "example": 1,
              "default": 1
            }
          },
          {
            "name": "userId",
            "in": "query",
            "required": false,
            "schema": {
              "type": "integer",
              "example": 1,
              "default": 1
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Likes status data returned",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "example": true
                    },
                    "likes": {
                      "type": "integer",
                      "example": 12
                    },
                    "hasLiked": {
                      "type": "boolean",
                      "example": true
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Missing parameters",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "500": {
            "description": "Internal error",
